def design(feats) -> Design:
    x, y = np.asarray(feats.x), np.asarray(feats.y)
    empty = Design(drivers=(), columns=(), products=(), loadings={})
    if x.shape[1] == 0 or min(np.sum(y == 0), np.sum(y == 1)) < 3:
        return empty
    p = stats.ttest_ind(x[y == 1], x[y == 0], axis=0, equal_var=False).pvalue
    p = np.where(np.isfinite(p), p, 1.0)
    j = int(np.argmin(p))
    if p[j] >= 0.01 / x.shape[1] or MAX_DRIVERS < 1:
        return empty
    fid = feats.ids[j]
    return Design(drivers=(fid,), columns=(fid,), products=(), loadings={})

